'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var Float32Array = require( '@stdlib/array/float32' );
var tryRequire = require( '@stdlib/utils/try-require' );


// VARIABLES //

var scurange = tryRequire( resolve( __dirname, './../lib/scurange.native.js' ) );
var opts = {
	'skip': ( scurange instanceof Error )
};


// TESTS //

tape( 'main export is a function', opts, function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof scurange, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 5', opts, function test( t ) {
	t.strictEqual( scurange.length, 5, 'has expected arity' );
	t.end();
});

tape( 'the function computes cumulative range', opts, function test( t ) {
	var expected;
	var x;
	var y;

	x = new Float32Array( [ 1.0, -2.0, -4.0, 5.0 ] );
	y = new Float32Array( x.length );
	expected = new Float32Array([
		0.0,
		3.0,
		5.0,
		9.0
	]);
	scurange( x.length, x, 1, y, 1);

	t.deepEqual( y, expected, 'returns expected values' );
	t.end();
});

tape( 'if N <= 0, the function returns y unchanged', opts, function test( t ) {
	var expected;
	var x;
	var y;

	x = new Float32Array( [ 1.0, 2.0, 3.0 ] );
	y = new Float32Array( [ 9.0, 9.0, 9.0 ] );
	expected = new Float32Array( [ 9.0, 9.0, 9.0 ]);
	scurange( 0, x, 1, y, 1);

	t.deepEqual( y, expected, 'returns expected values' );
	t.end();
});

tape( 'the function supports stride', opts, function test( t ) {
	var expected;
	var x;
	var y;

	x = new Float32Array([
		1.0,  // 0
		9.0,
		-2.0, // 1
		8.0,
		4.0   // 2
	]);
	expected = new Float32Array([
		0.0,
		3.0,
		6.0
	]);
	y = new Float32Array( x.length );
	scurange( 3, x, 2, y, 1);

	t.deepEqual( y.slice( 0, 3 ), expected, 'returns expected values' );
	t.end();
});

tape( 'the function supports negative stride', opts, function test( t ) {
	var expected;
	var x;
	var y;

	x = new Float32Array([
		4.0,  // 2
		0.0,
		-2.0, // 1
		0.0,
		1.0   // 0
	]);
	expected = new Float32Array([
		0.0,
		3.0,
		6.0
	]);
	y = new Float32Array( x.length );
	scurange( 3, x, -2, y, 1 );

	t.deepEqual( y.slice( 0, 3 ), expected, 'returns expected values' );
	t.end();
});

tape( 'NaN propagates forward', opts, function test( t ) {
	var x;
	var y;

	x = new Float32Array( [ 1.0, NaN, 3.0 ] );
	y = new Float32Array( x.length );
	scurange( x.length, x, 1, y, 1 );

	t.strictEqual( isnanf( y[1] ), true, 'returns expected values' );
	t.strictEqual( isnanf( y[2] ), true, 'returns expected values ' );
	t.end();
});

tape( 'the function supports view offsets', opts, function test( t ) {
	var expected;
	var x0;
	var x1;
	var y;

	x0 = new Float32Array([
		2.0,
		1.0,  // start
		-2.0,
		3.0,
		-1.0
	]);
	expected = new Float32Array([
		0.0,
		3.0,
		5.0
	]);
	y = new Float32Array( x0.length );

	x1 = new Float32Array( x0.buffer, x0.BYTES_PER_ELEMENT );
	scurange( 3, x1, 1, y, 1 );

	t.deepEqual( y.slice( 0, 3 ), expected, 'returns expected values' );
	t.end();
});
